/* IFES artwork, kept out of the app files on purpose.

   Everything here is base64 so it needs no server and no image requests, but it
   lives in its own file so the apps stay editable: a 270 KB HTML file that is
   90% image data is miserable to work on, and every edit has to carry the
   images along with it.

   Loaded with a plain <script src> tag rather than fetch(), because a script
   tag works when the page is opened straight off a disk and fetch() does not.

   To change a logo: replace the string. Nothing else needs touching.
     white — knockout wordmark, for the navy header and the PDF banner
     blue  — full-colour wordmark, for white cards
     mark  — the teardrop badge, bottom-left of every report page
*/
window.IFES_LOGOS = {
  white: "data:image/png;base64,",
  blue: "data:image/png;base64,",
  mark: "data:image/png;base64,"
};
